import { Button } from './Button.js';
import { Sheet } from './Sheet.js';
import { t } from '@/i18n/index.js';
import styles from './Confirm.module.css';

interface ConfirmProps {
  /** The question, as a question: "Sign out?" */
  title: string;
  /** One or more short paragraphs saying what will happen. */
  body: string | readonly string[];
  confirmLabel: string;
  cancelLabel?: string | undefined;
  /** Red, for an action that erases something or locks someone out. */
  danger?: boolean;
  /** True while the action runs; the sheet then refuses to close. */
  busy?: boolean;
  onConfirm: () => void;
  onCancel: () => void;
}

/**
 * The one confirmation in the app: a sheet with the question, what happens,
 * and two full-width buttons. Anything that signs out, erases or cannot be
 * undone goes through it, so every such moment looks and behaves the same.
 */
export function Confirm({
  title,
  body,
  confirmLabel,
  cancelLabel,
  danger = false,
  busy = false,
  onConfirm,
  onCancel,
}: ConfirmProps): React.JSX.Element {
  const paragraphs = typeof body === 'string' ? [body] : body;
  return (
    <Sheet
      title={title}
      onClose={() => {
        if (!busy) onCancel();
      }}
    >
      <div className={styles.body}>
        {paragraphs.map((text, position) => (
          <p key={text} className={position === 0 ? styles.lead : styles.note}>
            {text}
          </p>
        ))}
        <div className={styles.actions}>
          <Button variant={danger ? 'danger' : 'primary'} size="large" block busy={busy} onClick={onConfirm}>
            {confirmLabel}
          </Button>
          <Button variant="secondary" size="large" block disabled={busy} onClick={onCancel}>
            {cancelLabel ?? t('action.cancel')}
          </Button>
        </div>
      </div>
    </Sheet>
  );
}
